import * as RadioGroupPrimitive from "@radix-ui/react-radio-group"
import { StarIcon } from "lucide-react"
import * as React from "react"

import { cn } from "@/lib/utils"

const starRatingValues = [1, 2, 3, 4, 5] as const

type StarRatingProps = Omit<
  React.ComponentProps<typeof RadioGroupPrimitive.Root>,
  "children" | "defaultValue" | "onValueChange" | "value"
> & {
  value: number
  onValueChange: (value: number) => void
}

function StarRating({
  className,
  value,
  onValueChange,
  ...props
}: StarRatingProps) {
  return (
    <RadioGroupPrimitive.Root
      data-slot="star-rating"
      aria-label="Rating"
      className={cn(
        "flex w-fit items-center gap-1 rounded-md outline-none aria-invalid:ring-3 aria-invalid:ring-destructive/20",
        className
      )}
      value={String(value)}
      onValueChange={(nextValue) => onValueChange(Number(nextValue))}
      {...props}
    >
      {starRatingValues.map((rating) => (
        <RadioGroupPrimitive.Item
          type="button"
          key={rating}
          data-slot="star-rating-item"
          aria-label={`${rating} out of ${starRatingValues.length} stars`}
          className="rounded-sm p-1 text-muted-foreground transition-colors outline-none hover:text-amber-400 focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50"
          value={String(rating)}
        >
          <StarIcon
            aria-hidden="true"
            className={cn(
              "size-6",
              rating <= value && "fill-amber-400 text-amber-400"
            )}
          />
        </RadioGroupPrimitive.Item>
      ))}
    </RadioGroupPrimitive.Root>
  )
}

export { StarRating, type StarRatingProps }
